  const [bundle, setBundle] = useState<Bundle>(), [selected, setSelected] = useState(() => typeof window !== "undefined" ? new URL(window.location.href).searchParams.get("townMap") ? "town:"+new URL(window.location.href).searchParams.get("townMap")+":"+(new URL(window.location.href).searchParams.get("townReturnMap")??"") : new URL(window.location.href).searchParams.get("townMapCreate") ? "newtown:"+new URL(window.location.href).searchParams.get("townMapCreate")+":"+(new URL(window.location.href).searchParams.get("terrainMap")??"")+":" : new URL(window.location.href).searchParams.get("terrainMap") ?? "" : ""), [create, setCreate] = useState(false), [error, setError] = useState(""), [pending, setPending] = useState(true), [generation, setGeneration] = useState(0), localDirty = useRef(false);
