  const preferences=useRef<WorkspacePreferences|undefined>(undefined),[libraryBrowser,setLibraryBrowser]=useState(false);
  const cacheSource=useRef<Bundle|undefined>(undefined);
  const tileCache=useRef(new Map<string,{revision:number;tiles:TerrainDocument["tiles"];bytes:number}>());
  const [focusFrame,setFocusFrame]=useState<TerrainFrame|undefined>(()=>{if(typeof window==="undefined")return;try{const arrival=JSON.parse(new URL(location.href).searchParams.get("atlasArrival")??"null"),f=arrival?.frame;if(f&&[f.x,f.y,f.width,f.height].every(Number.isFinite)&&f.x>=0&&f.y>=0&&f.width>0&&f.height>0&&f.width<=1000000000&&f.height<=1000000000)return f;const p=arrival?.point;if(p&&[p.x,p.y].every(Number.isFinite)&&p.x>=0&&p.y>=0)return {x:Math.max(0,p.x-250),y:Math.max(0,p.y-250),width:500,height:500};}catch{}return;});
  const sourceDirty=useRef(false);const markSourceDirty=useCallback((value:boolean)=>{sourceDirty.current=value;onDirty(value||localDirty.current);},[onDirty]);
  const q = new URLSearchParams(); if (review) q.set("review", "1"); if (ordinary) q.set("ordinary", "1");
  const bindApi=useNativeApiUrl();
  const api = bindApi(`/api/worlds/${worldId}/terrain${q.size ? `?${q}` : ""}`);
  const readAuthority=useCallback(()=>ordinary||selected.startsWith("town:")||selected.startsWith("newtown:")?Promise.resolve(undefined):worldApi<Bundle>(`${api}${api.includes("?")?"&":"?"}${selected?`terrainMap=${encodeURIComponent(selected)}`:""}`),[ordinary,selected,worldApi,api]);
  const acceptAuthority=useCallback((fresh:Bundle|undefined)=>{if(fresh)setBundle(previous=>previous?refreshWorldResourceAuthority(previous,fresh):previous);},[]);
  useRefreshWorldResourceAuthority(worldId,readAuthority,acceptAuthority);
  const hierarchy=useWorldMapHierarchy(api,!ordinary);
  useEffect(() => { if (ordinary||selected.startsWith("town:")||selected.startsWith("newtown:")) return; let alive = true; const controller = new AbortController(); const previous=cacheSource.current,sourceId=previous?.document?.terrainId,known=sourceId?tileCache.current.get(sourceId):undefined,cacheQuery=known?`&knownTerrain=${sourceId}&knownRevision=${known.revision}`:"";worldApi<Bundle>(`${api}${api.includes("?") ? "&" : "?"}${selected ? `terrainMap=${encodeURIComponent(selected)}` : ""}${cacheQuery}`, "GET", undefined, controller.signal).then(value => { if (alive) { const doc=value.document;if(doc){const cached=tileCache.current.get(doc.terrainId);if(doc.tilesUnchanged){if(!cached||cached.revision!==doc.revision)throw Error("Cached terrain expired. Retry loading its accepted source.");doc.tiles=cached.tiles;}else{const bytes=doc.tiles.reduce((sum,t)=>sum+t.samples.length*8+64,0);tileCache.current.delete(doc.terrainId);tileCache.current.set(doc.terrainId,{revision:doc.revision,tiles:doc.tiles,bytes});while([...tileCache.current.values()].reduce((sum,c)=>sum+c.bytes,0)>16*1024*1024)tileCache.current.delete(tileCache.current.keys().next().value!);}}cacheSource.current=value;setBundle(value); setError(""); } }).catch(failure => { if (alive){setBundle(current=>current?{...current,document:null}:current);setError(message(failure));} }).finally(() => { if (alive) setPending(false); }); return () => { alive = false; controller.abort(); }; }, [api, selected, ordinary, generation,worldApi]);
  const dirtyChanged = useCallback((v: boolean) => { localDirty.current = v; onDirty(v||sourceDirty.current); }, [onDirty]);
  useEffect(() => () => onDirty(false), [onDirty]);
  function choose(id:string,frame?:TerrainFrame){guardHistoryNavigation("Open Selected Map",()=>performChoose(id,frame));}
  function performChoose(id: string,frame?:TerrainFrame) {if(id.startsWith("craft:")||id.startsWith("crafts:")){if(localDirty.current||sourceDirty.current){setError("Save or resolve the current map draft before opening craft maps.");return;}const u=new URL(location.href),[,craft,deck]=id.split(":");for(const key of ["townMap","townMapCreate","townReturnMap","interiorBuilding","interiorFloor","undergroundLevel","undergroundLibrary","undergroundNew","undergroundSite","atlasArrival","craft","craftNew","craftDeck","craftDeckNew","craftLibrary","craftRoute","craftArrival"])u.searchParams.delete(key);const map=u.searchParams.get("terrainMap");if(map)u.searchParams.set("craftReturnMap",map);if(craft){u.searchParams.set("craft",craft);if(deck)u.searchParams.set("craftDeck",deck);}else u.searchParams.set("craftLibrary","1");navigateNativeAtlas(u.pathname+u.search);return;}if(id.startsWith("underground:")){if(localDirty.current||sourceDirty.current){setError("Save or resolve the current map draft before opening underground maps.");return;}const u=new URL(location.href),level=id.slice(12);for(const key of ["undergroundNew","undergroundSite","undergroundSource","undergroundSourceRevision","undergroundReturn","atlasArrival"])u.searchParams.delete(key);if(level){u.searchParams.set("undergroundLevel",level);u.searchParams.delete("undergroundLibrary");}else{u.searchParams.set("undergroundLibrary","1");u.searchParams.delete("undergroundLevel");}navigateNativeAtlas(u.pathname+u.search);return;} if ((localDirty.current||sourceDirty.current) && !window.confirm("Leave this terrain draft? Save or download it before switching maps.")) return; dirtyChanged(false);setFocusFrame(frame);setBundle(current=>current?{...current,document:null}:current); setPending(true); setSelected(id);if(id===selected)setGeneration(n=>n+1); const url = new URL(window.location.href); url.searchParams.delete("terrainDetail"); url.searchParams.delete("townMap");url.searchParams.delete("townMapCreate");url.searchParams.delete("townReturnMap");url.searchParams.delete("interiorBuilding");url.searchParams.delete("interiorFloor");if(id.startsWith("town:")){const [,map,context]=id.split(":");url.searchParams.set("townMap",map);if(context)url.searchParams.set("townReturnMap",context);}else if(id.startsWith("newtown:")){const [,town,context]=id.split(":");url.searchParams.set("townMapCreate",town);if(context)url.searchParams.set("terrainMap",context);}else if (id) url.searchParams.set("terrainMap", id); else url.searchParams.delete("terrainMap"); replaceNativeAtlasUrl(url.pathname + url.search); }
