  return <section className={styles.workspace} aria-label="Atlas"><header className={styles.heading} hidden={!!bundle?.document&&!pending}><div><h2>Atlas</h2><button className="st-button is-secondary" onClick={()=>choose("crafts:")}>Craft Library / Create Craft</button><p>Shape the geography of {"this World"}. Begin with blank terrain, seeded geography or an imported heightmap, then sculpt and save it.</p></div>{canEdit && !review && <button className="st-button is-primary" disabled={pending} onClick={() => { if ((!localDirty.current&&!sourceDirty.current) || window.confirm("Leave the current terrain draft to create another map? Save or download it first.")) setCreate(true); }}>Create flat world</button>}</header>{(!bundle?.document||pending)&&<><button type="button" className="st-button is-secondary" onClick={()=>setLibraryBrowser(true)}>Switch Map</button><WorldMapBrowser worldId={worldId} review={review} open={libraryBrowser} currentId={bundle?.document?.id??""} hierarchy={hierarchy} maps={bundle?.maps??[]} editable={canEdit&&!review} onClose={()=>setLibraryBrowser(false)} onChoose={id=>{setLibraryBrowser(false);choose(id);}} onCreateWorld={()=>{setLibraryBrowser(false);setCreate(true);}} onCreateRegion={()=>setLibraryBrowser(false)}/></>}{error && <p role="alert" className={styles.feedback}>{error} <button className="st-button is-secondary" onClick={() => { setPending(true); setGeneration(n => n + 1); }}>Retry loading</button> <button className="st-button is-secondary" onClick={()=>choose("")}>Browse World maps</button></p>}{pending && <p role="status">Loading terrain…</p>}{bundle && <>{(!bundle.document||pending)&&<GuidedField label="World terrain map" help="Choose a saved heightmap in this World. Independent World maps keep their terrain. Linked regions share their specific parent’s accepted geography." controlClassName="st-control"><select value={selected} disabled={pending} onChange={e => choose(e.target.value)}><option value="">Choose a map</option>{bundle.maps.filter(m=>!m.parentMapId).map(map=><optgroup key={map.id} label={map.name}><option value={map.id}>{map.name} · World</option>{bundle.maps.filter(m=>m.parentMapId===map.id).map(m=><option key={m.id} value={m.id}>{m.name} · Region</option>)}</optgroup>)}{bundle.maps.filter(m=>m.parentMapId&&!bundle.maps.some(p=>p.id===m.parentMapId)).map(m=><option key={m.id} value={m.id}>{m.name} · parent unavailable</option>)}</select></GuidedField>}{!bundle.maps.length && <div className={styles.empty}><h3>Your geography begins here</h3><p>{canEdit ? "Create a flat world to start shaping mountains, valleys and shorelines." : "There are no heightmaps to review in this World."}</p></div>}{bundle.document && !pending && <Sculptor key={`${bundle.document.id}:${generation}`} hierarchy={hierarchy} preferences={preferences} onCreateWorld={()=>setCreate(true)} document={bundle.document} maps={bundle.maps} initialFrame={focusFrame} onNavigate={choose} api={api} review={review} editable={canEdit && bundle.canEdit && !review} onDirty={dirtyChanged} onSaved={revision => setBundle(current => current ? { ...current, maps: current.maps.map(m => m.id === selected ? { ...m, revision } : m) } : current)} onReload={() => { dirtyChanged(false); setPending(true); setGeneration(n => n + 1); }}/>}</>}{create && <TerrainSourceWorkshop worldId={worldId} api={api} onDirty={markSourceDirty} onClose={()=>setCreate(false)} onAccepted={result=>{setCreate(false);markSourceDirty(false);choose(result.id);}}/>}</section>;
